e <- new.env()
reg.finalizer(e, function(e) stop('finalizer failure'))
rm(e)
print(tryCatch({ invisible(gc()); 'gc returned' }, error=function(e) 'outer handler ran'))
invisible(gc())
print('only once')
f <- function(expr) tryCatch(expr, error=function(e) conditionMessage(e))
print(f(reg.finalizer(new.env(), sum)))
print(f(reg.finalizer(new.env(), function(e) NULL, NA)))
